// Package policy evaluates the tool-side guardrail policy generated by Forge.
// It never changes Guardian state; violations are diagnostics for CI and the UI.
package policy

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/radryc/guardian/internal/bundle"
	"github.com/radryc/guardian/internal/forge/diagnostic"
	"github.com/radryc/guardian/internal/paths"
	"gopkg.in/yaml.v3"
)

// Policy is the guardrail document.
type Policy struct {
	Version        int      `yaml:"version"`
	AllowedPushers []string `yaml:"allowedPushers,omitempty"`
	Require        struct {
		Labels         []string `yaml:"labels,omitempty"`
		SecretRefs     bool     `yaml:"secretRefs,omitempty"`
		ProbesFor      []string `yaml:"probesFor,omitempty"`
		AlertsFor      []string `yaml:"alertsFor,omitempty"`
		ResourceLimits bool     `yaml:"resourceLimits,omitempty"`
	} `yaml:"require,omitempty"`
	Limits struct {
		Replicas int `yaml:"replicas,omitempty"`
	} `yaml:"limits,omitempty"`
	Deny struct {
		Images     []string `yaml:"images,omitempty"`
		AssetTypes []string `yaml:"assetTypes,omitempty"`
	} `yaml:"deny,omitempty"`
}

// Load reads a guardrail policy. A missing file is not an error.
func Load(path string) (*Policy, bool, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, false, nil
		}
		return nil, false, err
	}
	var policy Policy
	if err := yaml.Unmarshal(data, &policy); err != nil {
		return nil, false, fmt.Errorf("parse %s: %w", path, err)
	}
	if policy.Version == 0 {
		policy.Version = 1
	}
	return &policy, true, nil
}

// Check evaluates the policy across partition directories.
func Check(partitionDirs []string, policyPath string) (diagnostic.List, error) {
	policy, found, err := Load(policyPath)
	if err != nil {
		return nil, err
	}
	var out diagnostic.List
	if !found || policy == nil {
		return out, nil
	}
	for _, dir := range partitionDirs {
		b, err := bundle.Load(dir, bundle.Options{ResolveIntentRefs: bundle.ResolveImageRefs})
		if err != nil {
			out.Add(diagnostic.Diagnostic{
				Severity: diagnostic.SeverityError,
				Code:     "FGE4000",
				Message:  err.Error(),
			})
			continue
		}
		out = append(out, evaluate(policy, b)...)
	}
	return out, nil
}

func evaluate(policy *Policy, b *bundle.Bundle) diagnostic.List {
	var out diagnostic.List
	add := func(message, path string) {
		out.Add(diagnostic.Diagnostic{
			Severity:  diagnostic.SeverityError,
			Code:      "FGE4001",
			Message:   message,
			Partition: b.PartitionName,
			Path:      path,
		})
	}

	labels := map[string]bool{}
	// Partition labels live in the config; re-read them from the config type.
	if part, _, err := bundle.NormalizePartitionManifest(b.ConfigContent, paths.PartitionConfig(b.PartitionName)); err == nil {
		for key := range part.Metadata.Labels {
			labels[key] = true
		}
		for key := range part.Spec.Labels {
			labels[key] = true
		}
	}
	for _, required := range policy.Require.Labels {
		if !labels[required] {
			add(fmt.Sprintf("partition is missing required label %q", required), "spec.labels")
		}
	}

	alertPrefix := paths.PartitionRoot(b.PartitionName) + "/alerts/"
	alertCount := 0
	for logicalPath := range b.ManagedFiles {
		if strings.HasPrefix(logicalPath, alertPrefix) {
			alertCount++
		}
	}
	if len(policy.Require.AlertsFor) > 0 && alertCount == 0 {
		add("partition has assets requiring alerts but no alert files", "alerts")
	}

	for intentName, intent := range b.IntentManifests {
		if len(policy.AllowedPushers) > 0 && !contains(policy.AllowedPushers, intent.Spec.TargetPusher) {
			add(fmt.Sprintf("intent %q uses pusher %q outside allowedPushers", intentName, intent.Spec.TargetPusher),
				fmt.Sprintf("intent/%s/spec/targetPusher", intentName))
		}
		probeTargets := map[string]bool{}
		for _, asset := range intent.Spec.Assets {
			if asset.Type == "Probe" {
				if target, ok := asset.Properties["target"].(string); ok {
					probeTargets[target] = true
				}
			}
		}
		for _, asset := range intent.Spec.Assets {
			assetPath := fmt.Sprintf("intent/%s/assets/%s", intentName, asset.Name)
			if contains(policy.Deny.AssetTypes, asset.Type) {
				add(fmt.Sprintf("asset %q type %q is denied by policy", asset.Name, asset.Type), assetPath)
			}
			if image, ok := asset.Properties["image"].(string); ok {
				for _, pattern := range policy.Deny.Images {
					if imageMatches(pattern, image) {
						add(fmt.Sprintf("asset %q image %q is denied by policy", asset.Name, image), assetPath)
					}
				}
			}
			if policy.Limits.Replicas > 0 {
				if replicas := intProperty(asset.Properties["replicas"]); replicas > policy.Limits.Replicas {
					add(fmt.Sprintf("asset %q replicas %d exceeds limit %d", asset.Name, replicas, policy.Limits.Replicas), assetPath)
				}
			}
			if contains(policy.Require.ProbesFor, asset.Type) && !probeTargets[asset.Name] {
				add(fmt.Sprintf("asset %q type %q requires a Probe targeting it", asset.Name, asset.Type), assetPath)
			}
			if policy.Require.SecretRefs {
				out = append(out, checkSecrets(b.PartitionName, intentName, asset.Name, asset.Properties)...)
			}
		}
	}
	return out
}

func checkSecrets(partition, intent, asset string, properties map[string]any) diagnostic.List {
	var out diagnostic.List
	env, _ := properties["env"].(map[string]any)
	for key, value := range env {
		if !sensitiveKey(key) {
			continue
		}
		switch v := value.(type) {
		case map[string]any:
			if ref, _ := v["secret_ref"].(string); strings.TrimSpace(ref) == "" {
				out.Add(diagnostic.Diagnostic{
					Severity:  diagnostic.SeverityError,
					Code:      "FGE6001",
					Message:   fmt.Sprintf("env %s on asset %q must use secret_ref", key, asset),
					Partition: partition,
					Path:      fmt.Sprintf("intent/%s/assets/%s/properties/env/%s", intent, asset, key),
				})
			}
		default:
			out.Add(diagnostic.Diagnostic{
				Severity:  diagnostic.SeverityError,
				Code:      "FGE6001",
				Message:   fmt.Sprintf("env %s on asset %q contains an inline secret value", key, asset),
				Partition: partition,
				Path:      fmt.Sprintf("intent/%s/assets/%s/properties/env/%s", intent, asset, key),
			})
		}
	}
	return out
}

func sensitiveKey(key string) bool {
	upper := strings.ToUpper(key)
	for _, marker := range []string{"TOKEN", "PASSWORD", "SECRET", "API_KEY", "PRIVATE_KEY"} {
		if strings.Contains(upper, marker) {
			return true
		}
	}
	return false
}

func imageMatches(pattern, image string) bool {
	pattern = strings.TrimSpace(pattern)
	if pattern == "" {
		return false
	}
	if strings.HasPrefix(pattern, "*") {
		return strings.HasSuffix(image, strings.TrimPrefix(pattern, "*"))
	}
	return pattern == image
}

func intProperty(value any) int {
	switch v := value.(type) {
	case int:
		return v
	case int64:
		return int(v)
	case float64:
		return int(v)
	case string:
		var parsed int
		_, _ = fmt.Sscanf(v, "%d", &parsed)
		return parsed
	}
	return 0
}

func contains(values []string, want string) bool {
	for _, value := range values {
		if value == want {
			return true
		}
	}
	return false
}

// PathFor resolves the policy path under a repository root.
func PathFor(root string) string {
	return filepath.Join(root, ".forge", "policy.yaml")
}
